// One gateway invocation lifecycle event -> the Plane ticket it is about and
// what to do with its agent:working chip. The triggers' data filter already
// dropped every turn no ticket command launched (Claude/Codex sessions etc.),
// and everything needed rides on data.context: no static data, no board map.
// Boards Krebs owns (managed/shadow execution) are listed in the n8n env var
// KREBS_FENCED_BOARDS (JSON array of board ids); Krebs keeps its own chips.
let fenced = [];
try {
  const raw = $env.KREBS_FENCED_BOARDS;
  fenced = raw ? JSON.parse(raw) : [];
} catch (error) {
  fenced = [];
}
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const env = items[i].json || {};
  const data = env.data || {};
  const ctx = data.context || {};
  if (!ctx.workspace || !ctx.board_id || !ctx.ticket_id) continue;
  if (Array.isArray(fenced) && fenced.includes(ctx.board_id)) continue;
  const type = String(env.type || '');
  out.push({
    json: {
      action: type.endsWith('.started') ? 'add' : 'remove',
      ws: ctx.workspace,
      board: ctx.board_id,
      ticketId: ctx.ticket_id,
      ticketKey: ctx.ticket_key ?? null,
      reason: ctx.reason ?? null,
      agentId: data.target_agent_id ?? null,
      eventType: type,
      eventId: env.id ?? null,
      correlationid: env.correlationid ?? null,
    },
    pairedItem: { item: i },
  });
}
return out;

// Resolve the chip label BY NAME on this board. A board without one
// (CANDY/CANDYS carry a soft-deleted row Plane will not recreate) simply gets
// no chip: skip quietly, never fail the lane.
const LABEL = 'agent:working';
// The Plane HTTP nodes run with On Error = Continue, so a failed request
// arrives here as { error } instead of failing the execution. 404/410 means
// the ticket (or its board) was deleted while the agent's turn was running:
// there is no chip left to set, so the item is skipped and the execution stays
// green. Any other failure (auth, 5xx) still fails it, with the ticket named.
const GONE = [404, 410];
function httpStatus(err) {
  if (err && typeof err === 'object') {
    const candidates = [err.httpCode, err.statusCode, err.status, err.response && err.response.status, err.cause && err.cause.status];
    for (const v of candidates) {
      const n = Number(v);
      if (Number.isInteger(n) && n >= 100 && n < 600) return n;
    }
  }
  const text = err && typeof err === 'object' ? `${err.message || ''} ${err.description || ''}` : String(err || '');
  const m = text.match(/\b([1-5]\d\d)\b/);
  return m ? Number(m[1]) : null;
}
function failure(step, t, err) {
  const status = httpStatus(err);
  if (GONE.includes(status)) return null;
  const detail = err && typeof err === 'object' ? err.message || err.description || JSON.stringify(err) : String(err);
  return new Error(`${step} failed for ${t.ticketKey || t.ticketId} (board ${t.board}): HTTP ${status ?? '?'} ${String(detail).slice(0, 200)}`);
}
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const target = $('Chip — Target').itemMatching(i).json;
  const body = items[i].json || {};
  if (body.error) {
    const err = failure('Chip — List Labels', target, body.error);
    if (err) throw err;
    continue;
  }
  const labels = Array.isArray(body.results) ? body.results : [];
  const hit = labels.find((l) => l && typeof l.name === 'string' && l.name.trim().toLowerCase() === LABEL);
  if (!hit) continue;
  out.push({ json: { ...target, labelId: hit.id }, pairedItem: { item: i } });
}
return out;

// Read-modify-write of the ticket's label set. No-op writes are dropped: the
// chip is already on (add) or already gone (remove). A ticket that was deleted
// mid-turn (404/410, or a soft-deleted row) is skipped, not written.
// The Plane HTTP nodes run with On Error = Continue, so a failed request
// arrives here as { error } instead of failing the execution. 404/410 means
// the ticket (or its board) was deleted while the agent's turn was running:
// there is no chip left to set, so the item is skipped and the execution stays
