    }
  }
  const text = err && typeof err === 'object' ? `${err.message || ''} ${err.description || ''}` : String(err || '');
  const m = text.match(/\b([1-5]\d\d)\b/);
  return m ? Number(m[1]) : null;
}
function failure(step, t, err) {
  const status = httpStatus(err);
  if (GONE.includes(status)) return null;
  const detail = err && typeof err === 'object' ? err.message || err.description || JSON.stringify(err) : String(err);
  return new Error(`${step} failed for ${t.ticketKey || t.ticketId} (board ${t.board}): HTTP ${status ?? '?'} ${String(detail).slice(0, 200)}`);
}
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const t = $('Chip — Resolve Label').itemMatching(i).json;
  const issue = items[i].json || {};
  if (issue.error) {
    const err = failure('Chip — Read Issue', t, issue.error);
    if (err) throw err;
    continue;
  }
  if (issue.deleted_at) continue;
  const current = (issue.labels || [])
    .map((l) => (l && typeof l === 'object' ? l.id : l))
    .filter(Boolean);
  const has = current.includes(t.labelId);
  if (t.action === 'add' ? has : !has) continue;
  const labels = t.action === 'add' ? [...current, t.labelId] : current.filter((id) => id !== t.labelId);
  out.push({ json: { ...t, labels }, pairedItem: { item: i } });
}
return out;

// The ticket can also vanish between the read and the write. Write Labels runs
// with On Error = Continue so that race lands here: 404/410 is the same no-op
// as a ticket already gone; anything else fails the execution, ticket named.
// The Plane HTTP nodes run with On Error = Continue, so a failed request
